    }
// zbr:selfhost/TypeChecker.zbr:10960
    if (_zbr_at(dm.params.items, 0).type_) |pt| {
// zbr:selfhost/TypeChecker.zbr:10961
        if (_zbr_val(pt) == .named) {
            const ptn = pt.named;
